const PortfolioEngine=function(){const e=document.getElementById("portfolio-grid");return{init:async function(){if(e)try{e.innerHTML='\n            <div class="col-span-full flex flex-col items-center justify-center py-20 space-y-4">\n                <div class="w-12 h-12 border-4 border-supernova-orange border-t-transparent rounded-full animate-spin"></div>\n                <p class="text-cosmic-blue font-medium animate-pulse">Curating Innovation...</p>\n            </div>\n        ';let t=[];if("undefined"!=typeof firebase&&firebase.apps.length){const e=firebase.firestore(),n=await e.collection("student_projects").orderBy("date","desc").get();n.empty||(t=n.docs.map(e=>({id:e.id,...e.data()})))}if(0===t.length){const e=await fetch("assets/data/projects.json");e.ok&&(t=await e.json())}!function(t){if(0===t.length)return void(e.innerHTML='<p class="col-span-full text-center text-gray-500 py-20">No projects found in the vault yet.</p>');e.innerHTML=t.map(e=>`\n            <div class="group bg-white rounded-3xl overflow-hidden shadow-xl hover:shadow-2xl transition-all duration-500 transform hover:-translate-y-2 border border-gray-100">\n                <div class="relative h-64 overflow-hidden">\n                    <img src="${e.image}" alt="${e.title}" class="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" loading="lazy">\n                    <div class="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 flex items-end p-6">\n                        <div class="flex space-x-3 translate-y-4 group-hover:translate-y-0 transition-transform duration-500">\n                            <a href="${e.demoUrl||"#"}" target="_blank" class="bg-supernova-orange text-white p-3 rounded-full hover:bg-orange-700 transition-colors shadow-lg">\n                                <i data-lucide="external-link" class="w-5 h-5"></i>\n                            </a>\n                            <a href="${e.videoUrl||"#"}" target="_blank" class="bg-white text-cosmic-blue p-3 rounded-full hover:bg-gray-100 transition-colors shadow-lg">\n                                <i data-lucide="play" class="w-5 h-5"></i>\n                            </a>\n                        </div>\n                    </div>\n                    <div class="absolute top-4 right-4 bg-supernova-orange text-white px-3 py-1 rounded-full text-xs font-bold shadow-lg">\n                        ${e.category}\n                    </div>\n                </div>\n                <div class="p-8">\n                    <div class="flex items-center space-x-3 mb-4">\n                        <div class="w-10 h-10 rounded-full bg-cosmic-blue/10 flex items-center justify-center">\n                            <i data-lucide="user" class="w-5 h-5 text-cosmic-blue"></i>\n                        </div>\n                        <div>\n                            <h4 class="font-bold text-cosmic-blue leading-tight">${e.studentName}</h4>\n                            <p class="text-xs text-gray-500">${e.studentAge} Years Old</p>\n                        </div>\n                    </div>\n                    <h3 class="text-xl font-bold font-poppins text-cosmic-blue mb-3 group-hover:text-supernova-orange transition-colors">${e.title}</h3>\n                    <p class="text-gray-600 text-sm leading-relaxed mb-6 line-clamp-3">\n                        ${e.description}\n                    </p>\n                    <div class="flex flex-wrap gap-2 pt-4 border-t border-gray-100">\n                        ${(e.tags||[]).map(e=>`<span class="text-[10px] font-bold uppercase tracking-wider text-gray-400 bg-gray-50 px-2 py-1 rounded border border-gray-100">${e}</span>`).join("")}\n                    </div>\n                </div>\n            </div>\n        `).join("")}(t),window.gsap&&gsap.from("#portfolio-grid > div",{y:50,opacity:0,duration:.8,stagger:.15,ease:"power2.out",clearProps:"all"}),window.lucide&&window.lucide.createIcons()}catch(t){console.error("[STEMulus] Portfolio Engine Error:",t),e.innerHTML='<p class="col-span-full text-center text-gray-500 py-20">Unable to load the showcase at this time. Please check back soon!</p>'}}}}();document.addEventListener("DOMContentLoaded",PortfolioEngine.init);